#!/usr/bin/env bash
# =============================================================================
# rab-patch-v3.1.sh  —  SATU patch untuk semua upgrade & perbaikan (v3.0 -> v3.1)
#
# Memasang:
#   [config] CLAUDE.md v3.1, .claude/{agents,commands,skills}, tools/*.sh, docs/AUDIT_KONFIGURASI_*.md
#   [app]    js/m.user.role.js  (perbaikan: tanpa Ext.Viewport, master-detail, Form Access di form New Role,
#                                Copy From, Select All bertingkat, mode lihat/edit, id update)
#            js/m.user.system.js (Apply Role otomatis: Update All / Access Only, id record unik,
#                                 tombol Add/Apply Role simetris, ikon trash header, hapus hardcode ../dev/)
#
# Prinsip keselamatan (selaras CLAUDE.md §1.1, §13, §14):
#   - semua file yang akan ditimpa DIBACKUP di LUAR docroot ($HOME/proyekgmn-backups/patch-v3.1-<waktu>/)
#   - file aplikasi hanya ditimpa bila isinya VERSI YANG DIKENAL (dibuat sesi ini); versi tak dikenal TIDAK disentuh
#     (kecuali --force), versi baru disimpan di folder backup untuk Anda bandingkan
#   - setiap file JS baru dilint (js-lint-lite); gagal => file otomatis dikembalikan
#   - idempotent: aman dijalankan ulang; ada rollback.sh otomatis; tidak menyentuh database
#
# Pemakaian (jalankan dari akar proyek, mis. /home/myadmin/proyekgmn-dev):
#   bash rab-patch-v3.1.sh --dry-run          # lihat apa yang AKAN berubah, tanpa menulis apa pun
#   bash rab-patch-v3.1.sh                    # terapkan
#   opsi: --project DIR  --skip-app  --skip-config  --force  --move-stray-bak
# =============================================================================
set -u
VERSION="3.1"
PROJECT="$(pwd)"; DRY=0; FORCE=0; SKIP_APP=0; SKIP_CONFIG=0; MOVE_BAK=0

usage() { sed -n '2,26p' "$0" | sed 's/^# \{0,1\}//'; }
while [ $# -gt 0 ]; do
  case "$1" in
    --project) PROJECT="${2:?--project butuh path}"; shift 2 ;;
    --dry-run) DRY=1; shift ;;
    --force) FORCE=1; shift ;;
    --skip-app) SKIP_APP=1; shift ;;
    --skip-config) SKIP_CONFIG=1; shift ;;
    --move-stray-bak) MOVE_BAK=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Opsi tidak dikenal: $1"; usage; exit 2 ;;
  esac
done

c_ok()   { printf '  [OK]    %s\n' "$*"; }
c_skip() { printf '  [SKIP]  %s\n' "$*"; }
c_do()   { printf '  [UBAH]  %s\n' "$*"; }
c_warn() { printf '  [WARN]  %s\n' "$*"; }
c_err()  { printf '  [GAGAL] %s\n' "$*"; }
N_CHANGED=0; N_SKIPPED=0; N_WARN=0; N_FAIL=0

for t in tar base64 sha256sum awk cmp; do command -v "$t" >/dev/null 2>&1 || { echo "Perintah '$t' tidak ditemukan."; exit 2; }; done
PROJECT="$(cd "$PROJECT" 2>/dev/null && pwd -P)" || { echo "Folder proyek tidak ada."; exit 2; }
if [ ! -d "$PROJECT/php-crud" ] || [ ! -d "$PROJECT/js" ]; then
  echo "Bukan akar proyek rab-project (tidak ada php-crud/ dan js/ di: $PROJECT)."
  echo "Jalankan dari akar proyek atau pakai --project /home/myadmin/proyekgmn-dev"; exit 2
fi

TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
PAYLOAD_LINE="$(awk '/^__PAYLOAD__$/ {print NR+1; exit}' "$0")"
tail -n +"$PAYLOAD_LINE" "$0" | base64 -d | tar xz -C "$TMP" 2>/dev/null || { echo "Payload rusak. Unduh ulang patch."; exit 2; }

STAMP="$(date +%Y%m%d-%H%M%S)-$$"
BK="${RAB_BACKUP_DIR:-$HOME/proyekgmn-backups}/patch-v${VERSION}-${STAMP}"
case "$BK" in "$PROJECT"/*) echo "Direktori backup tidak boleh di dalam proyek ($BK). Set RAB_BACKUP_DIR."; exit 2 ;; esac
MANIFEST="$BK/manifest.txt"

echo "============================================================"
echo " rab-patch v$VERSION   proyek: $PROJECT"
[ "$DRY" = 1 ] && echo " MODE: DRY-RUN (tidak ada file yang ditulis)" || echo " backup: $BK"
echo "============================================================"
if [ "$DRY" = 0 ]; then
  # folder backup HARUS baru dan unik (mkdir tanpa -p pada daun): tidak pernah memakai/menghapus backup run lain
  mkdir -p "$(dirname "$BK")" && mkdir "$BK" || { echo "Gagal membuat direktori backup unik: $BK"; exit 2; }
  mkdir -p "$BK/files"; : > "$MANIFEST"
fi

# backup_file <rel>  : simpan versi lama (atau catat bahwa file baru) untuk rollback
backup_file() {
  local rel="$1"
  [ "$DRY" = 1 ] && return 0
  if [ -e "$PROJECT/$rel" ]; then mkdir -p "$BK/files/$(dirname "$rel")"; cp -p "$PROJECT/$rel" "$BK/files/$rel"; echo "RESTORE $rel" >> "$MANIFEST"
  else echo "REMOVE $rel" >> "$MANIFEST"; fi
}
# put_file <src> <rel>
put_file() {
  local src="$1" rel="$2"
  backup_file "$rel"
  mkdir -p "$PROJECT/$(dirname "$rel")" && cp "$src" "$PROJECT/$rel"
}
restore_file() {   # kembalikan satu file dari backup (dipakai saat lint gagal)
  local rel="$1"
  if [ -f "$BK/files/$rel" ]; then cp -p "$BK/files/$rel" "$PROJECT/$rel"; else rm -f "$PROJECT/$rel"; fi
}

# ------------------------------------------------------------------ [config]
if [ "$SKIP_CONFIG" = 0 ]; then
  echo; echo "[1/3] Konfigurasi Claude Code (CLAUDE.md, .claude/, tools/, docs/)"
  while IFS= read -r f; do
    rel="${f#"$TMP/config/"}"; dest="$PROJECT/$rel"
    if [ -f "$dest" ] && cmp -s "$f" "$dest"; then N_SKIPPED=$((N_SKIPPED+1)); continue; fi
    if [ "$DRY" = 1 ]; then c_do "$rel"; else put_file "$f" "$rel"; c_do "$rel"; fi
    N_CHANGED=$((N_CHANGED+1))
  done < <(find "$TMP/config" -type f | sort)
  [ "$DRY" = 0 ] && chmod +x "$PROJECT"/tools/*.sh 2>/dev/null
  [ "$N_SKIPPED" -gt 0 ] && c_skip "$N_SKIPPED file konfigurasi sudah sama dengan v$VERSION"
  [ -f "$PROJECT/verify_patch_diff.sh" ] && c_warn "ada verify_patch_diff.sh lama di akar proyek; yang dipakai CLAUDE.md v$VERSION adalah tools/verify_patch_diff.sh (yang lama tidak diubah)" && N_WARN=$((N_WARN+1))
else
  echo; echo "[1/3] Konfigurasi: dilewati (--skip-config)"
fi

# ------------------------------------------------------------------ [app]
LINT="$TMP/config/tools/js-lint-lite.sh"
if [ "$SKIP_APP" = 0 ]; then
  echo; echo "[2/3] Perbaikan aplikasi (JS)"
  for rel in js/m.user.role.js js/m.user.system.js; do
    new="$TMP/app/$rel"; cur="$PROJECT/$rel"
    if [ ! -f "$cur" ]; then c_warn "$rel tidak ditemukan di proyek: dilewati"; N_WARN=$((N_WARN+1)); continue; fi
    h_cur="$(sha256sum "$cur" | cut -d' ' -f1)"; h_new="$(sha256sum "$new" | cut -d' ' -f1)"
    if [ "$h_cur" = "$h_new" ]; then c_skip "$rel sudah versi terbaru"; N_SKIPPED=$((N_SKIPPED+1)); continue; fi
    known=0; grep -q "^$h_cur  $rel$" "$TMP/known_old.txt" && known=1
    if [ "$known" = 0 ] && [ "$FORCE" = 0 ]; then
      c_warn "$rel: isi file TIDAK dikenal (sudah Anda ubah sendiri?). Tidak ditimpa."
      c_warn "         versi baru + perbandingan disimpan; periksa lalu gabungkan manual atau jalankan ulang dengan --force"
      if [ "$DRY" = 0 ]; then mkdir -p "$BK/NEW/$(dirname "$rel")"; cp "$new" "$BK/NEW/$rel"; echo "         versi baru: $BK/NEW/$rel"; fi
      echo "         selisih: $(diff "$cur" "$new" | grep -c '^[<>]') baris berbeda  (diff -u $cur $new)"
      N_WARN=$((N_WARN+1)); continue
    fi
    [ "$known" = 0 ] && c_warn "$rel: versi tidak dikenal, ditimpa karena --force"
    if [ "$DRY" = 1 ]; then c_do "$rel (versi lama dikenal -> v$VERSION)"; N_CHANGED=$((N_CHANGED+1)); continue; fi
    put_file "$new" "$rel"
    out="$(bash "$LINT" "$cur" "$PROJECT" 2>&1)"; rc=$?
    if [ "$rc" -ne 0 ] && [ "$FORCE" = 0 ]; then
      restore_file "$rel"; c_err "$rel gagal gerbang js-lint-lite; DIKEMBALIKAN ke versi lama"; echo "$out" | grep -E '^(FAIL|WARN)' | sed 's/^/         /'
      N_FAIL=$((N_FAIL+1)); continue
    fi
    c_do "$rel -> v$VERSION (lint: $(echo "$out" | tail -1 | sed 's/^---- //'))"
    N_CHANGED=$((N_CHANGED+1))
  done
else
  echo; echo "[2/3] Aplikasi: dilewati (--skip-app)"
fi

# ------------------------------------------------------------------ higiene docroot
echo; echo "[3/3] Higiene docroot (file backup/dump yang bisa diunduh lewat web)"
STRAY="$(find "$PROJECT" -maxdepth 4 \( -name '*.bak' -o -name '*.bak-*' -o -name '*.bak_*' -o -name '*.orig' \) -not -path "$PROJECT/ext-3.4.1/*" -not -path "$PROJECT/.git/*" 2>/dev/null | sort)"
[ -d "$PROJECT/tmp_bak" ] && STRAY="$STRAY"$'\n'"$PROJECT/tmp_bak"
STRAY="$(echo "$STRAY" | sed '/^$/d')"
if [ -z "$STRAY" ]; then c_ok "tidak ada file backup di dalam folder proyek"
else
  echo "$STRAY" | sed "s#^$PROJECT/#         #"
  if [ "$MOVE_BAK" = 1 ] && [ "$DRY" = 0 ]; then
    while IFS= read -r p; do
      rel="${p#"$PROJECT/"}"; mkdir -p "$BK/stray/$(dirname "$rel")"; mv "$p" "$BK/stray/$rel" && echo "MOVED $rel" >> "$MANIFEST"
    done <<< "$STRAY"
    c_do "dipindah ke $BK/stray/ (dapat dikembalikan lewat rollback.sh)"
  else
    c_warn "dibiarkan. Jalankan ulang dengan --move-stray-bak untuk memindahkannya ke luar docroot"; N_WARN=$((N_WARN+1))
  fi
fi

# ------------------------------------------------------------------ rollback.sh + ringkasan
NOBK=0
if [ "$DRY" = 0 ] && [ ! -s "$MANIFEST" ] && [ ! -d "$BK/NEW" ] && [ ! -d "$BK/stray" ]; then
  rm -rf "$BK"; NOBK=1       # tidak ada perubahan: jangan tinggalkan backup/rollback kosong yang menyesatkan
fi
if [ "$DRY" = 0 ] && [ "$NOBK" = 0 ]; then
  cat > "$BK/rollback.sh" <<ROLL
#!/usr/bin/env bash
# Mengembalikan semua file yang diubah oleh rab-patch v$VERSION ($STAMP)
set -u
PROJECT="$PROJECT"; BK="$BK"
while read -r op rel; do
  case "\$op" in
    RESTORE) cp -p "\$BK/files/\$rel" "\$PROJECT/\$rel" && echo "dikembalikan: \$rel" ;;
    REMOVE)  rm -f "\$PROJECT/\$rel" && echo "dihapus (file baru): \$rel" ;;
    MOVED)   mkdir -p "\$PROJECT/\$(dirname "\$rel")" && mv "\$BK/stray/\$rel" "\$PROJECT/\$rel" && echo "dikembalikan (backup lama): \$rel" ;;
  esac
done < "\$BK/manifest.txt"
echo "Rollback selesai."
ROLL
  chmod +x "$BK/rollback.sh"
fi

echo; echo "============================================================"
echo " Ringkasan: diubah=$N_CHANGED  dilewati=$N_SKIPPED  peringatan=$N_WARN  gagal=$N_FAIL"
if [ "$DRY" = 1 ]; then
  echo " (dry-run: belum ada yang ditulis. Jalankan tanpa --dry-run untuk menerapkan.)"
elif [ "$NOBK" = 1 ]; then
  echo " Tidak ada perubahan: backup tidak dibuat (semua sudah v$VERSION)."
else
  echo " Backup & rollback : $BK/rollback.sh"
fi
echo "------------------------------------------------------------"
echo " LANGKAH BERIKUTNYA (manual):"
echo "  1. Browser: Ctrl+F5 pada halaman User Role dan User System (JS di-cache), lalu buka DevTools > Console"
echo "     (harus 0 error merah; abaikan 'Permissions policy violation: unload') dan Network (tanpa 403/404 *CRD.php)."
echo "  2. Jalankan: bash tools/modul-gate.sh m.user.role   dan   bash tools/modul-gate.sh m.user.system"
echo "  3. Uji alur: New User Role (Add form + Copy From) -> Save; Edit matriks (Select All bertingkat);"
echo "     User System: pilih role -> grid Form Access terisi (Update All / Access Only)."
echo "  4. Keputusan yang masih menunggu Anda: lihat bagian 3 di docs/AUDIT_KONFIGURASI_2026-11-23.md"
echo "     (cross-call User System -> m.user.roleCRD.php, alur status PO, verifikasi CheckColumn.js)."
echo "  Patch ini TIDAK mengubah database. Akses form User Role (id 167) untuk user admin tetap lewat SQL migrasi."
echo "============================================================"
[ "$N_FAIL" -eq 0 ]
exit $?
__PAYLOAD__

